/* Rust reads as an accent at any size in a bar, but as TEXT on paper it lands at
   4.40:1. Text gets a darker sibling; the marks keep the brand colour. */
:root{--rust-text:#b8431f}
.rail .gut .val,.rail .gut.rest .val,.magnote,.margin .rustnote,caption.cut .backup,
.sentence .fig,caption.cut .cs .fig,.aim,.phclause,.phcount b,.bars .cut,
.picker button.on .q,.hero .rustnote{color:var(--rust-text)}
.freshness{margin:10px 0 2px;text-align:center;font-size:12px;color:var(--muted,#6b6560);
  letter-spacing:.02em}
