.credit{margin:2px 0 10px;text-align:center;font-size:12px;color:var(--muted,#6b6560)}
.credit a{color:inherit;text-decoration:underline;text-underline-offset:2px}
.aimday{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--muted,#6b6560)}
