.hand .kbd{display:none;font-weight:400;color:var(--smoke)}
.hand:focus-within .kbd,body.kbnav .hand .kbd{display:inline}

/* the seam sits above the evidence, in a wrapper that does not scroll sideways */
#results{overflow-x:visible}
.tscroll{overflow-x:auto}
.tscroll table.reports{min-width:760px}
.cut{position:sticky;top:0;z-index:6;background:var(--paper);border-top:2px solid var(--rust);
  padding:8px 10px;display:flex;align-items:baseline;justify-content:space-between;gap:20px;
  flex-wrap:wrap}
.cut .cs{font-family:'Instrument Serif',Georgia,serif;font-size:20px;line-height:1.2;
  color:var(--ink);flex:1 1 320px;min-width:280px}
.cut .cs .fig{font-family:'IBM Plex Mono',monospace;color:var(--rust-text);font-size:.9em}
.cut .cs .aside,.cut .cs .clause{font-size:.7em}
