.srclinks{margin:0;padding-left:17px}
.srclinks li{margin:5px 0;line-height:1.5}
.srclinks a{color:var(--rust-text,#a3421f)}
.srclinks .mono{font-family:'IBM Plex Mono',ui-monospace,monospace;font-size:.94em}

/* Twenty-six years is 320 months. Fitted to the width each bar was 1px: a hairline
   nobody can read or hit. They keep a usable width and the rail scrolls instead. */
.rail.open[data-rail=when] .track{overflow-x:auto;overscroll-behavior-x:contain}
.rail.open[data-rail=when] .months,
.rail.open[data-rail=when] .axis{min-width:var(--mw,100%)}
.rail.open[data-rail=when] .mo{min-width:5px}
.whenhint{font:11.5px/1.4 Archivo,system-ui,sans-serif;color:var(--ash);margin-top:3px}

.specimen.opens{cursor:pointer;border-radius:5px;margin:0 -8px;padding:4px 8px 5px;
  transition:background .12s}
.specimen.opens:hover,.specimen.opens:focus-visible{background:#f3efe8}
.specimen.opens:focus-visible{outline:2px solid var(--rust);outline-offset:1px}
.opencue{color:var(--rust-text,#a3421f);font-weight:600;white-space:nowrap}

.starter.flash{animation:flashin 1.4s ease-out}
@keyframes flashin{0%{background:#f6e3d8}60%{background:#f6e3d8}100%{background:transparent}}
@media(prefers-reduced-motion:reduce){.starter.flash{animation:none;background:#f6e3d8}}

.aimopts{display:flex;gap:6px;flex-wrap:wrap;margin-top:5px}
.aimopts button{display:inline-flex;gap:7px;align-items:baseline;padding:4px 10px;font-size:12.5px}
.aimopts em{font-style:normal;color:var(--ash);font-size:11.5px}
.aimopts b{font-variant-numeric:tabular-nums}

.aimat{position:relative}
.aimsug{position:absolute;left:0;right:0;top:calc(100% + 3px);z-index:40;background:#fff;
  border:1px solid var(--line);border-radius:6px;box-shadow:0 8px 24px rgba(20,16,12,.13);
  max-height:290px;overflow-y:auto;min-width:430px}
.aimsug[hidden]{display:none}
.sug{display:flex;align-items:baseline;gap:9px;padding:6px 11px;cursor:pointer;
  border-bottom:1px solid #f2efe9}
.sug:last-child{border-bottom:0}
.sug:hover,.sug.on{background:#f6f2ec}
.sug .sk{flex:0 0 132px;font:600 9.5px/1.5 Archivo,system-ui,sans-serif;letter-spacing:.07em;
  color:#fff;background:#8d857b;border-radius:3px;padding:1px 6px;text-align:center}
.sug .sk-operator{background:#8c4a2f}.sug .sk-tail{background:#3f6b57}
.sug .sk-period{background:#4a5d80}.sug .sk-zone{background:#7a5a2e}
.sug .sk-jasc{background:#5d4a72}.sug .sk-q{background:#6f6a63}
.sug .sl{flex:1;min-width:0;font-size:13.5px;color:var(--ink);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sug b{font-variant-numeric:tabular-nums;font-size:12.5px;color:var(--ash)}
@media(max-width:700px){.aimsug{min-width:0}.sug .sk{flex-basis:96px;font-size:8.5px}}

#q.flash{animation:qflash 1.4s ease-out}
@keyframes qflash{0%,55%{background:#f6e3d8;box-shadow:0 0 0 3px rgba(196,75,40,.25)}
  100%{background:#fff;box-shadow:none}}
@media(prefers-reduced-motion:reduce){#q.flash{animation:none;background:#f6e3d8}}

.aimat select{font-size:12.5px;padding:5px 6px;border:1px solid var(--line);border-radius:5px;
  background:#fff;color:var(--ink);max-width:150px}
.sughead{font:600 9.5px/1.7 Archivo,system-ui,sans-serif;letter-spacing:.08em;color:#fff;
  padding:1px 11px;position:sticky;top:0;z-index:1}
.sughead.sk-operator{background:#8c4a2f}.sughead.sk-tail{background:#3f6b57}
.sughead.sk-period{background:#4a5d80}.sughead.sk-zone{background:#7a5a2e}
.sughead.sk-jasc{background:#5d4a72}.sughead.sk-q{background:#6f6a63}
.sug .sw{color:var(--ash);font-size:11.5px;white-space:nowrap}

.sug.nought{opacity:.62;cursor:default}
.sug.nought:hover{background:transparent}
.sug.nought b{color:var(--ash)}
</style>
</head>
<body>
<a class="skip" href="#results">Skip to the results</a>
<main class="wrap" id="main">
<div id="hero" class="hero"></div>
<div class="tabs" id="tabs"></div>
<p class="freshness" id="freshness"></p>
<p class="credit">Inspired by Rory Kennedy's
  <a href="https://en.wikipedia.org/wiki/Downfall:_The_Case_Against_Boeing"
     target="_blank" rel="noopener">Downfall: The Case Against Boeing</a>.
  Built by Henk van Ess &copy; 2026.</p>

<div class="panel on" id="p-search">
  <div class="scope"></div>
  <div class="hint" hidden>Pick a question to fill the search in for you, or build your own below.
  In the results, any value you point at can be clicked to filter by it, and hovering explains it.
  The grey band under each report is the mechanic's own words, word for word.</div>
  <div class="starter" id="starters"></div>
  <div class="filters">
    <input id="q" list="qlist" autocomplete="off" aria-label="Any words in the mechanic's write-up" placeholder="Any words in the write-up, e.g. bird strike">
    <datalist id="qlist"></datalist>
    <select id="operator" aria-label="Operator"><option value="">Any operator</option></select>
    <label class="fld">From<input id="from" type="date"></label>
    <label class="fld">Up to<input id="to" type="date"></label>
    <button onclick="search(0)">Search</button>
    <button class="ghost" onclick="resetAll()">Clear</button>
  </div>
  <details class="morefilters" id="morefilters">
    <summary>More filters <span class="muted" id="mfCount"></span></summary>
    <div class="filters sub">
      <select id="make" aria-label="Manufacturer"><option value="">Any manufacturer</option></select>
      <input id="model" aria-label="Aircraft model" placeholder="Model, e.g. 7378H4">
      <input id="part" aria-label="Part name" placeholder="Part name, e.g. BEARING">
      <input type="hidden" id="jasc">
      <select id="ata" aria-label="Aircraft system"><option value="">Any aircraft system</option></select>
      <select id="nature" aria-label="What was found"><option value="">Anything found</option></select>
      <select id="crew" aria-label="What the crew did"><option value="">Anything the crew did</option></select>
      <select id="condition" aria-label="Part condition"><option value="">Any part condition</option></select>
      <select id="discovered" aria-label="How it was found"><option value="">Found by any method</option></select>
      <select id="stage" aria-label="Stage of flight"><option value="">Any stage of flight</option></select>
      <select id="zone" aria-label="Zone on the aircraft"><option value="">Anywhere on the aircraft</option></select>
      <input id="tail" aria-label="Tail number" placeholder="Tail number, e.g. 583UP">
      <select id="corrosion" aria-label="Corrosion level"><option value="">Any corrosion level</option></select>
      <select id="cracked" aria-label="Cracking recorded"><option value="">Cracked or not</option><option value="1">Cracking recorded</option></select>
      <select id="minhours" aria-label="Airframe age"><option value="">Any airframe age</option><option value="20000">20,000 hours or more</option><option value="50000">50,000 hours or more</option><option value="75000">75,000 hours or more</option></select>
    </div>
  </details>
  <div class="chips" id="chips"></div>
  <div class="scope" id="unresolved"></div>
  <div class="bar">
    <span class="count" id="count"></span>
    <button class="ghost" id="exportBtn" onclick="exportCsv()">Export CSV</button>
    <button class="ghost" id="copyBtn" onclick="copyLink()">Copy link</button>
    <span id="copied" class="muted"></span>
  </div>
  <div id="results"></div>
  <div class="bar"><button class="ghost" id="more" onclick="more()" style="display:none">Load 100 more</button></div>
</div>

<div class="panel" id="p-patterns">
  <div class="scope"></div>
  <p class="lead">The same selection, counted. Set filters on the Search tab and these follow. Click any bar to filter on it.</p>
  <div class="card"><h2>Reports per month</h2><div class="bars" id="trend"></div></div>
  <div class="two">
    <div class="card"><h2>Aircraft system</h2><div class="bars" id="by-ata"></div></div>
    <div class="card"><h2>Airline</h2><div class="bars" id="by-op"></div></div>
  </div>
  <div class="two">
    <div class="card"><h2>Model</h2><div class="bars" id="by-model"></div></div>
    <div class="card"><h2>Part</h2><div class="bars" id="by-part"></div></div>
    <div class="card"><h2>What was found</h2>
      <p class="muted note" id="note-nature"></p><div class="bars" id="by-nature"></div></div>
    <div class="card"><h2>What the crew did</h2>
      <p class="muted note" id="note-crew"></p><div class="bars" id="by-crew"></div></div>
    <div class="card"><h2>How it was found</h2><div class="bars" id="by-disc"></div></div>
    <div class="card"><h2>Words that stand out here</h2>
      <p class="muted">The vocabulary of this selection against all <span class="corpus-n"></span>reports. Useful for
      finding the term the trade actually uses, which is rarely the one you searched for.</p>
      <div id="phrases"></div></div>
  </div>
</div>

<div class="panel" id="p-aircraft">
  <div class="scope"></div>
  <p class="lead">One aircraft at a time. Type a tail number, or click one anywhere in the tool.</p>
  <div class="bar"><input id="tail-in" aria-label="Tail number" placeholder="Tail number, e.g. N583UP" style="min-width:220px">
    <button onclick="loadTail(document.getElementById('tail-in').value)">Open dossier</button></div>
  <div id="tail-out"></div>
  <h3>Most written-up aircraft in the current selection</h3>
  <div id="offenders"></div>
</div>

<div class="panel" id="p-leads">
  <div class="scope"></div>
  <p class="lead">Where to start. Both tables compare the last 90 days with what came before.</p>
  <div class="card"><h2>Aircraft with a sudden cluster</h2>
    <div class="muted" style="margin-bottom:8px">More write-ups in the last 90 days than in this aircraft's whole earlier record here. Worth asking the airline about.</div>
    <div id="leads"></div></div>
  <div class="card"><h2>What is rising</h2>
    <div class="bar"><select id="spike-by" aria-label="What to rank by" onchange="loadSpikes()">
      <option value="ata">By aircraft system</option>
      <option value="part">By part</option><option value="model">By model</option>
      <option value="operator">By airline</option><option value="ata">By system</option></select></div>
    <div id="spikes"></div></div>
</div>

<div class="panel" id="p-defect">
  <div class="scope"></div>
  <p class="lead">One part number, failing the same way, on many aircraft and at more than one airline. That is a fleet problem, not an incident.</p>
  <div id="defects"></div>
</div>


<div class="panel" id="p-fleet">
  <div class="scope"></div>
  <h1>One airline, one type</h1>
  <p class="lede">A count of reports means little on its own. What matters is how many separate
  aircraft it touched. Ten write-ups on one airframe is a bad machine. Ten write-ups across ten
  airframes is a fleet problem.</p>
  <div class="bar">
    <select id="fl-op" aria-label="Operator"><option value="">Pick an airline code</option></select>
    <input id="fl-model" placeholder="Model, optional, e.g. 7377H4">
    <button onclick="loadFleet()">Show fleet</button>
  </div>
  <div id="fleet-out"></div>
</div>

<div class="panel" id="p-emerging">
  <div class="scope"></div>
  <h1>Defects that are new</h1>
  <p class="lede">A defect that is new tells you more than one that is merely common. These are
  parts and systems being written up now that barely appeared before, so the pattern is still
  forming. Small numbers, read them as a tip rather than a finding.</p>
  <div class="bar"><select id="em-by" aria-label="What to rank by" onchange="loadEmerging()">
    <option value="part">By part</option><option value="jasc">By system</option>
    <option value="condition">By part condition</option><option value="partnumber">By part number</option></select>
    <select id="em-days" aria-label="Time window" onchange="loadEmerging()"><option value="120">Last 120 days</option>
    <option value="180">Last 180 days</option><option value="365">Last year</option></select></div>
  <div id="emerging"></div>
</div>

<div class="panel" id="p-clusters">
  <div class="scope"></div>
  <h1>Same airline, same system, same day</h1>
  <p class="lede">When one airline writes up the same system on several different aircraft on a
  single day, the cause is rarely the aircraft. It is a batch of parts, a procedure, a supplier or
  a shared inspection. This is the pattern that turns a maintenance note into a story.</p>
  <div class="bar"><select id="cl-min" aria-label="Minimum aircraft in a cluster" onchange="loadClusters()">
    <option value="3">3 aircraft or more</option><option value="4">4 or more</option>
    <option value="6">6 or more</option><option value="10">10 or more</option></select>
    <select id="cl-kind" aria-label="Kind of cluster" onchange="loadClusters()">
      <option value="oneoff">One-offs only</option><option value="all">Everything</option>
      <option value="routine">Recurring, probably scheduled</option></select></div>
  <div id="clusters"></div>
</div>

<div class="panel" id="p-structure">
  <div class="scope"></div>
  <h1>Corrosion and cracks</h1>
  <p class="lede">The slow story. Corrosion is graded by the FAA. Level 2 means it went past what
  the manufacturer allows and needed repair. Level 3 is an urgent airworthiness concern: the
  operator must notify the regulator within three days and act across the whole fleet, not just on
  that aircraft. Level 1 stays within limits and is not reportable, which is why you never see it
  here.</p>
  <div id="structure"></div>
</div>

<div class="panel" id="p-age">
  <div class="scope"></div>
  <h1>Do old airframes break differently?</h1>
  <p class="lede">Hours and cycles are two different kinds of old. A short-haul aircraft piles up
  cycles fast and hours slowly, and since every flight pressurises and depressurises the hull, it
  is cycles that drive cracking. Hours wear out the things that simply run.</p>
  <div class="bar"><select id="ag-by" aria-label="Measure of age" onchange="loadAgeing()">
    <option value="hours">By hours flown</option><option value="cycles">By takeoff-and-landing cycles</option></select></div>
  <div id="ageing"></div>
</div>

<div class="panel" id="p-engines">
  <div class="scope"></div>
  <h1>Engines</h1>
  <p class="lede">Handle with care. Only about three in a hundred reports name the engine, so this
  is a count inside a small subset, not a failure rate per engine in service. Use it to find cases
  to check, never to rank manufacturers.</p>
  <div id="engines"></div>
</div>

<div class="panel" id="p-consequences">
  <div class="scope"></div>
  <h1>What the crew actually had to do</h1>
  <p class="lede" id="crewLede">Not what broke, but what it forced.</p>
  <div class="bar"><select id="cq-by" aria-label="Group by" onchange="loadConsequences()">
    <option value="operator">By airline</option><option value="model">By model</option>
    <option value="make">By manufacturer</option></select></div>
  <div id="consequences"></div>
</div>

<div class="panel" id="p-found">
  <div class="scope"></div>
  <h1>How was it found?</h1>
  <p class="lede">A crack found by eddy current or X-ray was invisible from the outside. One found
  by eye was not. Splitting a system's findings by method tells you whether trouble is being caught
  by instruments before anyone could see it, or noticed only once it showed. Not every report falls
  either way: functional checks and unrecorded methods make up a large share, and they are listed too.</p>
  <p class="muted">This follows whatever you have filtered on the Search tab.</p>
  <div id="found"></div>
</div>

<div id="case-wrap" onclick="if(event.target.id==='case-wrap')closeCase()"><div id="case-box"></div></div>

<div class="panel" id="p-compare">
  <div class="scope"></div>
  <p class="lead">Two airlines or models side by side. These are raw counts: a bigger airline files more reports, so this is a starting point, not a score.</p>
  <div class="bar">
    <select id="cmp-field" aria-label="What to compare"><option value="operator">Airlines</option><option value="model">Models</option><option value="make">Manufacturers</option></select>
    <input id="cmp-a" aria-label="First value to compare" placeholder="A, a name or code, e.g. Southwest"><input id="cmp-b" aria-label="Second value to compare" placeholder="B, a name or code, e.g. Delta">
    <button onclick="loadCompare()">Compare</button></div>
  <div class="two"><div id="cmp-a-out"></div><div id="cmp-b-out"></div></div>
</div>

<div class="panel" id="p-terms">
  <div class="scope"></div>
  <p class="lead">Everything in this tool, in plain words. The shorthand comes from maintenance logs; the codes come from the FAA's own tables.</p>
  <div class="two">
    <div class="card"><h2>What you are reading</h2><dl id="gloss"></dl></div>
    <div class="card"><h2>FAA codes</h2><div id="codetables"></div></div>
  </div>
</div>

<div class="panel" id="p-method">
  <div class="scope"></div>
  <div class="card">
    <h2>Where this comes from</h2>
    <p>Operators and mechanics must report failures, malfunctions and defects to the FAA. Those Service Difficulty Reports are public. This holds every report the FAA published for <strong id="m-range"></strong>, <strong id="m-total"></strong> in total, taken from the yearly files at <span class="muted">external.apic4e.faa.gov/sdrs/retrieve/SDR-YYYY.csv</span>. There is no FAA API; the files are downloaded whole and rebuilt here.</p>
    <h2 style="margin-top:14px">What it cannot tell you</h2>
    <p>This is not an accident database and not a safety ranking. A high count can mean an old fleet, a thorough maintenance department, or simply a large airline. Nothing here is divided by fleet size or flying hours, because the FAA file does not contain either.</p>
    <p>A write-up is a defect that maintenance caught. That is usually the system working, not failing.</p>
    <h2 style="margin-top:14px">About the codes</h2>
    <p>Most coded fields are decoded from the FAA's own lookup tables, which the FAA publishes as a
    zip file on the SDRS front page. This site carries the edition dated July 2026, shipped with the
    code so you can check it. Run against all <span class="corpus-n"></span>reports, those tables resolve every code that
    actually occurs, with none left over.</p>
    <p>Four fields are not in that zip and come from elsewhere, named here rather than left to be
    discovered. Corrosion grades come from FAA Order 8300.12 and EASA IMRBPB IP 119. Operator
    designators come from two FAA lists merged: the December 2006 Air Carrier/Operator
    cross-reference, whose host has since been retired, and the current list of certificated 121 and
    135 operators. The old edition is kept on purpose, because a carrier that stopped filing before
    2006, TWA among them, appears in no list published today. FAA regions and district offices are
    compiled from FAA designations. Some historic district offices resolve in neither list and are
    shown as the raw code.</p>
    <p>An earlier version of this page decoded the letters from a third-party copy of the tables,
    checked against three codes in the FAA's field instructions. That copy was wrong in at least one
    place: it had <code>R</code> as engine flameout, where the FAA's own table has <code>R</code> as
    a partial loss of rpm or power and <code>X</code> as flameout. Checking three cells said nothing
    about the rest. The tables now come from the FAA directly.</p>
    <h2>What this tool promises</h2>
    <p>Cold start to a quotable sentence on your clipboard in six gestures: click a starter question,
    click the operator in the WHO rail, drag a range across WHEN, click Case sheet on a row, read
    the quote, click Copy all three. Before this rewrite the same task took about eighteen, ten of
    them keystrokes inside two date fields. Nothing ships here that lengthens it.</p>
    <p>One thing here is not decoded from the FAA's own tables: the corrosion grades, which are not
    in the FAA zip. Those definitions come from FAA Order 8300.12 and EASA IP 119 and are labelled as
    such wherever they appear. The four-letter operator designator is expanded from two FAA sources merged: the Air Carrier/Operator cross-reference, December 2006 edition, whose host has since been retired, and the current list of certificated 121 and 135 operators. <span class="opgap-resolved"></span> The rest are shown exactly as filed. Any name can be stale where a carrier has merged, been
    renamed, or kept filing under a legacy code, so check current ownership before you publish.</p>
    <h2 style="margin-top:14px">Before you publish</h2>
    <p>Open the original report through the FAA's own query page, check the tail number in the FAA registry, and put the finding to the airline. Read the write-up itself rather than the count: the mechanic's sentence is the evidence.</p>
  </div>
</div>
</div>
</main>
<div id="tip"></div>

<script>
/* Twee data die makkelijk verward worden: tot wanneer de meldingen lopen (van de
   FAA) en wanneer wij voor het laatst gekeken hebben (van ons). */
/* Eén zware inspectie levert meerdere meldingen op: de monteur schrijft elke
   vondst apart op, met een eigen controlenummer. 429.652 van de 1.489.061
   meldingen met een staartnummer zitten in zo'n dagreeks van vijf of meer, dus
   dit is geen randgeval. Zonder deze regel leest een reeks als zeven incidenten
   in plaats van als één controlebeurt. */
function sameDayRuns(rows){
  const g={};
  (rows||[]).forEach(x=>{
    const t=(x.RegistryNNumber||"").trim(), d=(x.DifficultyDate||"").trim();
    if(!t||!d)return;
    const k=t+"|"+d;
    (g[k]=g[k]||{t:t,d:d,n:0}).n++;
  });
  const runs=Object.values(g).filter(r=>r.n>4).sort((a,b)=>b.n-a.n);
  if(!runs.length)return "";
  const one=r=>`<b>${num(r.n)}</b> of them on N${esc(r.t)} on ${esc(ukDate(r.d))}`;
  let body;
  if(runs.length===1){
    body=`${one(runs[0])}`;
  }else{
    const rest=runs.length-2;
    body=runs.slice(0,2).map(one).join("; ")+(rest>0?`; and ${rest} more like it`:"");
  }
  return `<div class="runnote">Some of what you see here is one inspection, not one
    fault each: ${body}. A mechanic writes up every finding separately, so a heavy
    check on a single aircraft fills a page. Count events, not rows.</div>`;
}
function showFreshness(){
  const box=document.getElementById("freshness"); if(!box)return;
  fetch("api/freshness").then(r=>r.json()).then(d=>{
    if(!d||!d.newest_report)return;
    const day=x=>new Date(x+"T00:00:00Z").toLocaleDateString("en-GB",
      {day:"numeric",month:"long",year:"numeric",timeZone:"UTC"});
    let t="Reports up to and including <b>"+day(d.newest_report)+"</b>";
    if(d.rows)t+=", "+d.rows.toLocaleString("en-GB")+" in total";
    if(d.refreshed_at){
      const r=new Date(d.refreshed_at);
      const mins=Math.round((Date.now()-r.getTime())/60000);
      const when = mins<90 ? mins+" minutes ago"
        : mins<48*60 ? Math.round(mins/60)+" hours ago"
        : r.toLocaleDateString("en-GB",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"});
      t+=". Checked against the FAA "+when+", three times a day";
    }
    box.innerHTML=t+".";
  }).catch(()=>{});
}
showFreshness();

/* Suggesties in het vrije tekstveld komen uit de woorden die de monteurs zelf
   schreven, niet uit een verzonnen lijst. Wie CRAC typt krijgt CRACKED, CRACK,
   CRACKS, met hun aantallen erbij. */
let qSugTimer=null, qSugSeq=0;
async function qSuggest(v){
  const list=document.getElementById("qlist"); if(!list)return;
  const mine=++qSugSeq;
  try{
    const r=await(await fetch("api/vocab?q="+encodeURIComponent(v)+"&limit=10")).json();
    if(mine!==qSugSeq)return;
    list.innerHTML=(r.rows||[]).map(row=>{
      const term=String(row.term||"").toLowerCase().replace(/"/g,"&quot;");
      const n=(row.n||0).toLocaleString("en-GB");
      return '<option value="'+term+'" label="'+n+' reports"></option>';
    }).join("");
  }catch(e){}
}
document.addEventListener("input",e=>{
  if(!e.target||e.target.id!=="q")return;
  const v=e.target.value.trim();
  clearTimeout(qSugTimer);
  if(v.length<3){const l=document.getElementById("qlist"); if(l)l.innerHTML=""; return}
  qSugTimer=setTimeout(()=>qSuggest(v),180);
});
const TABS=[["p-search","Search"],["p-patterns","Patterns"],["p-aircraft","Aircraft"],["p-fleet","Fleet"],
            ["p-leads","Story leads"],["p-emerging","New defects"],["p-clusters","Same day, many aircraft"],
            ["p-defect","Same defect"],["p-structure","Corrosion & cracks"],["p-age","Old airframes"],
            ["p-engines","Engines"],["p-consequences","What the crew did"],["p-found","How it was found"],
            ["p-compare","Compare"],["p-terms","Every code explained"],["p-method","Method"]];
const FIELDS=["q","operator","make","model","part","ata","jasc","nature","crew","condition","stage","zone","tail","discovered",
              "corrosion","cracked","minhours","from","to"];
const LABEL={q:"Text",operator:"Operator",make:"Manufacturer",model:"Model",part:"Part",ata:"System",jasc:"Exact system",
             nature:"Found",crew:"Crew action",condition:"Part condition",stage:"Stage of flight",zone:"Zone on the aircraft",tail:"Tail number",discovered:"How found",
             corrosion:"Corrosion",cracked:"Cracking",minhours:"At least this many hours",
             from:"From",to:"To"};
const STARTERS=[["Smoke or fumes in the cabin",{nature:"B"}],["Cracks found",{q:"crack"}],
  ["Engine shut down in flight",{crew:"E"}],["Unscheduled landing",{crew:"A"}],
  ["Bird strikes",{q:"bird"}],["Landing gear trouble",{ata:"32"}],
  ["Something burning",{q:"burn"}],["Fuel leaks",{q:"fuel leak"}],
  ["Oxygen masks dropped",{crew:"G"}],["Cabin lost pressure",{crew:"I"}],
  ["Aborted take-off",{crew:"C"}],["Corrosion past the limit",{corrosion:"2"}],
  ["Urgent corrosion, level 3",{corrosion:"3"}],["Damage no one could see",{discovered:"E"}],
  ["Engine flameout",{nature:"X"}],["Uncontained engine failure",{nature:"T"}],
  ["Old airframes, 50,000 hours plus",{minhours:"50000"}],["Something fell off in flight",{nature:"D"}]];
let ATA={},CODES={},GLOSS={},FCOUNT={},TOTAL=0,offset=0,OPGAP=null;

const el=id=>document.getElementById(id);
/* The airline's name, everywhere. The raw designator stays the filter value. */
function opName(o){const e=(CODES.operator||{})[String(o||"").trim()];return e?e.label:(o||"")}
function opFull(o){const e=(CODES.operator||{})[String(o||"").trim()];return e?`${e.label} (${o})`:(o||"")}
const esc=s=>(s==null?"":String(s)).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function codeObj(grp,v){const e=CODES[grp]&&CODES[grp][String(v||"").trim()];
  return (e&&typeof e==="object")?e:(e?{label:e}:null)}
function code(grp,v){const e=codeObj(grp,v);return e?(e.short||e.label):(v||"")}
/* a code shown as its meaning, hoverable for the FAA's own wording, clickable to filter */
function cc(grp,v,field){
  const e=codeObj(grp,v); if(!v)return '<span class="absent">not recorded</span>';
  if(!e)return esc(v);
  const short=e.short||e.label;
  const on=field?` onclick="setFilter('${field}','${esc(v)}')"`:"";
  /* When the plain English and the FAA wording say the same thing there is nothing
     to explain, so the value keeps its click but loses the dotted underline and the
     hollow tooltip, and recedes. That leaves the exceptional values as the only dark
     text in these columns. */
  const bare=!e.note && String(e.faa||"").toUpperCase()===String(e.label).toUpperCase();
  /* A filed code is a fact, even when it says "None". Only an empty field is absent. */
  if(bare) return `<span class="c dull"${on}>${esc(short)}</span>`;
  const tip=[e.label,e.faa?"FAA wording: "+e.faa:"",e.note||""].filter(Boolean).join(". ");
  return `<span class="term c" data-fixed="${esc(short)}|${esc(tip)}"${on}>${esc(short)}</span>`;
}

/* Which views obey the filter and which do not was the one thing the old strip
   never said. Short label on screen, full sentence for a screen reader. */
const VIEW_GROUPS=[
  ["Narrows to what you selected",
   "Narrows to what you selected",
   ["p-search","p-patterns","p-aircraft","p-found"]],
  ["Ignore your selection",
   "These ignore your selection. Each answers from all {N}reports, or from a slice you set inside the panel",
   ["p-fleet","p-leads","p-emerging","p-clusters","p-defect","p-structure","p-age",
    "p-engines","p-consequences"]],
  ["Reference","Reference",["p-compare","p-terms","p-method"]],
];
function renderTabs(){
  const label=id=>{const t=TABS.find(x=>x[0]===id);return t?t[1]:id};
  el("tabs").innerHTML=VIEW_GROUPS.map(([head,full0,ids])=>{const full=full0.replace("{N}",TOTAL?num(TOTAL)+" ":"");return `<div class="vgroup"><span class="vlab" title="${esc(full)}">${esc(head)}</span>
      <div class="vrow" role="tablist" aria-label="${esc(full)}">${ids.map(id=>
        `<button class="tab" role="tab" data-p="${id}" id="tab-${id}"
          aria-controls="${id}" aria-selected="false" tabindex="-1">${esc(label(id))}</button>`).join("")}
      </div></div>`;}).join("");
  document.querySelectorAll('#tabs .tab[data-p]').forEach(t=>t.onclick=()=>show(t.dataset.p));
}
function toggleMore(){}

/* Which panels narrow to the current filter, and which always answer for the whole
   corpus. Saying it out loud is the only thing that stops a reporter reading a
   corpus-wide number as an answer to the question they just asked. */
const FOLLOWS_FILTER=["p-search","p-patterns","p-found"];
function filterWords(){
  const out=[];
  for(const [k,v] of params()){
    if(k==="hero")continue;
    let shown=v;
    if(k==="operator")shown=opFull(v);
    else if(k==="ata")shown=ATA[v]||v;
    else if(k==="jasc")shown=(CODES.jasc&&CODES.jasc[v]&&CODES.jasc[v].label)||v;
    else if(k==="zone")shown=code("part_location",v);
    else if(["nature","discovered","stage","corrosion"].includes(k))shown=code(k,v);
    else if(k==="crew")shown=code("precaution",v);
    out.push((LABEL[k]||k)+": "+shown);
  }
  return esc(out.join(", "));
}
function scopeLine(id){
  const box=document.querySelector("#"+id+" .scope"); if(!box)return;
  const n=[...params().keys()].length;
  const shown=(LAST_TOTAL!=null)?LAST_TOTAL:(heroData&&heroData.total!=null?heroData.total:null);
  /* Search already states the count in its own bar; a second line would only repeat it */
  /* two tables with two different scopes cannot share one sentence */
  if(id==="p-search"||id==="p-aircraft"){box.className="scope";box.innerHTML="";return}
  if(FOLLOWS_FILTER.includes(id)){
    /* with nothing filtered this only repeats the hero, so it stays out of the way */
    box.className="scope follows";
    box.innerHTML=n
      ? `Showing <strong>your selection</strong>${shown!=null?`, ${num(shown)} reports`:""}.`
      : "";
  }else{
    box.className="scope whole"+(n?" warn":"");
    box.innerHTML=n
      ? `This view always answers for <strong>all ${num(TOTAL)} reports</strong>.
         It does not narrow to your current selection
         (${filterWords()}).`
      : `All ${num(TOTAL)} reports.`;
  }
}
/* Roving tabindex is per tablist, not per page. The page has four: the hero
   rail picker and the three view groups. Treating them as one group left every
   tab at -1, which took the whole strip out of the tab order. */
function rove(){
  document.querySelectorAll('[role="tablist"]').forEach(list=>{
    const tabs=[...list.querySelectorAll('[role="tab"]')];
    if(!tabs.length)return;
    const keep=tabs.find(x=>x.getAttribute("aria-selected")==="true")||tabs[0];
    tabs.forEach(x=>x.setAttribute("tabindex",x===keep?"0":"-1"));
  });
}
function show(id){
  document.querySelectorAll('#tabs [role="tab"]').forEach(x=>{
    const on=x.dataset.p===id;
    x.classList.toggle("on",on); x.setAttribute("aria-selected",String(on));
  });
  rove();
  document.querySelectorAll(".panel").forEach(x=>x.setAttribute("role","tabpanel"));
  if(!popping&&booted){
    const u=new URLSearchParams(location.search);
    id==="p-search"?u.delete("view"):u.set("view",id.slice(2));
    if(id!=="p-aircraft")u.delete("aircraft");
    if(u.toString()!==location.search.slice(1))history.pushState(null,"","?"+u.toString());
  }

  document.querySelectorAll(".panel").forEach(x=>x.classList.toggle("on",x.id===id));
  if(id==="p-patterns")loadPatterns(); if(id==="p-aircraft")loadOffenders();
  if(id==="p-leads"){loadLeads();loadSpikes();} if(id==="p-defect")loadDefects();
  if(id==="p-emerging")loadEmerging(); if(id==="p-clusters")loadClusters();
  if(id==="p-structure")loadStructure(); if(id==="p-age")loadAgeing();
  if(id==="p-engines")loadEngines(); if(id==="p-consequences")loadConsequences();
  if(id==="p-found")loadFound();
  scopeLine(id);
}
const URL_KNOWN=new Set([...FIELDS,"view","hero","case","aircraft","ca","cb","cf"]);
function strayParams(){
  return [...new URLSearchParams(location.search).keys()].filter(k=>!URL_KNOWN.has(k));
}
function dropRefused(k){
  delete UNRESOLVED[k];
  const e=el(k); if(e)e.value="";
  const u=new URLSearchParams(location.search); u.delete(k);
  history.replaceState(null,"","?"+u.toString()); chips(); search(0);
}
function dropStray(k){
  const u=new URLSearchParams(location.search); u.delete(k);
  history.replaceState(null,"","?"+u.toString()); search(0);
}
/* set the moment the reporter chooses to read everything; cleared by Clear */
let REVEALED=false;
function revealAll(){goResults()}
/* scrolling to a 36px strip with twelve of the questions still folded away landed
   the reader in the middle of the page with nothing that looked like a question */
function showStarters(){
  const s=el("starters"); if(!s)return;
  s.classList.add("all");
  const mq=el("moreQ"); if(mq)mq.textContent="fewer";
  const y=s.getBoundingClientRect().top+scrollY-90;
  scrollTo({top:y,behavior:"smooth"});
  s.classList.add("flash");
  setTimeout(()=>s.classList.remove("flash"),1400);
}
function params(){const p=new URLSearchParams();FIELDS.forEach(k=>{const v=el(k)&&el(k).value.trim();if(v)p.set(k,v)});return p}
/* one clickable cell for a "MAKE MODEL" string, so it means the same in every table */
function cellModel(v){
  if(!v||!v.trim())return '<span class="absent">not recorded</span>';
  return `<span class="c" onclick="setModel('${esc(v.trim())}')">${esc(v.trim())}</span>`;
}
function setModel(key){
  const i=key.indexOf(" ");
  clearFieldsQuiet(["make","model"]);
  el("make").value=i<0?key:key.slice(0,i);
  el("model").value=i<0?"":key.slice(i+1);
  show("p-search"); search(0); showChange();
}
function clearFieldsQuiet(keep){}
function setFilter(k,v){
  if(!el(k))return; el(k).value=v; show("p-search"); search(0); showChange();
}
/* after a filter click, put the controls, the chips and the count on screen together,
   so the reporter can see what changed rather than landing mid-table */
function showChange(){
  const p=el("p-search"); if(!p)return;
  const anchor=el("chips")&&el("chips").offsetHeight?el("chips"):p;
  const y=anchor.getBoundingClientRect().top+scrollY-(el("tabs").getBoundingClientRect().height+90);
  if(scrollY>y)scrollTo({top:Math.max(0,y),behavior:"smooth"});
}

/* A filter the reader cannot see is a filter they will misread. Whenever one of the
   folded controls carries a value, the panel opens itself and says how many. */
const HIDDEN_FIELDS=["make","model","part","jasc","ata","nature","crew","condition","stage",
                     "zone","tail","discovered","corrosion","cracked","minhours"];
/* Which of the fifteen controls no rail can draw. Saying so is the honest half of
   "two routes to one selection": a reporter must not wait for a mark that cannot exist. */
const NO_RAIL={q:"the mechanic's words",make:"manufacturer",model:"model",part:"part name",
               condition:"part condition",discovered:"how it was found",stage:"stage of flight",
               corrosion:"corrosion level",cracked:"cracking",minhours:"airframe hours",
               jasc:"exact system",ata:"system"};
function syncControls(){
  /* a control holding a value carries a rust edge, so the two routes never disagree
     about what is set */
  FIELDS.forEach(k=>{
    const e=el(k); if(!e)return;
    e.classList.toggle("landed",!!(e.value&&e.value.trim()));
  });
  const box=el("hero"); if(!box)return;
  /* and every mark that IS the current value reads as taken, not as available */
  const p=params();
  box.querySelectorAll("[data-take]").forEach(n=>{
    const [kind,key]=n.dataset.take.split("|");
    const f={zone:"zone",operator:"operator",tail:"tail",crew:"crew"}[kind];
    n.classList.toggle("taken",!!(f&&p.get(f)===key));
  });
}
function railBlind(){
  const p=params(), out=[];
  for(const [k] of p){ if(NO_RAIL[k])out.push(NO_RAIL[k]); }
  return out;
}
function syncMoreFilters(){
  const d=el("morefilters"); if(!d)return;
  const n=HIDDEN_FIELDS.filter(k=>{const e=el(k);return e&&e.value.trim()}).length;
  el("mfCount").textContent=n?`(${n} active)`:"";
  d.classList.toggle("active",!!n);
  if(n)d.open=true;
}
/* Measured server-side and filled in at boot. The numbers that used to sit here
   were counted against a three-year file and were still on the page when the file
   reached twenty-six years. */
const NO_OPERATOR={label:"No operator named",
  faa:"Some reports name no operator. The filers who leave it blank are usually not the operator."};
const UNRESOLVED={};
function chips(){
  const p=params(), out=[];
  for(const k in UNRESOLVED)
    out.push(`<span class="chip warn">${LABEL[k]||k}: ${esc(UNRESOLVED[k])}
      <em>&mdash; not a value in this data</em>
      <b onclick="delete UNRESOLVED['${k}'];chips();search(0)">&times;</b></span>`);
  for(const [k,v] of p){
    if(k in UNRESOLVED)continue;      /* a rejected value gets one chip, not two */
    let shown=v;
    if(k==="ata")shown=ATA[v]||v;
    if(k==="operator")shown=opFull(v);
    if(k==="jasc")shown=(CODES.jasc&&CODES.jasc[v]&&CODES.jasc[v].label)||v;
    ["nature","discovered","stage","condition","corrosion"].forEach(g=>{if(k===g)shown=code(g,v)});
    if(k==="crew")shown=code("precaution",v);
    if(k==="zone")shown=code("part_location",v);
    if(k==="cracked")shown="recorded"; if(k==="minhours")shown=Number(v).toLocaleString("en")+" hours";
    out.push(`<span class="chip">${LABEL[k]||k}: ${esc(shown)}<b onclick="setFilter('${k}','')">&times;</b></span>`);
  }
  el("chips").innerHTML=out.join("");
  const warn=el("unresolved");
  if(warn){
    const n=Object.keys(UNRESOLVED).length;
    warn.className=n?"scope whole warn":"scope";
    warn.innerHTML=n?`One value in this link is not in this data, so no search was run. There is no
      number on this page to quote.`:"";
  }
}

async function search(off){
  offset=off||0;
  const p=params();p.set("limit",100);p.set("offset",offset);
  /* start from what the address bar already holds, so view, aircraft, case and the
     comparison survive every search instead of being reconstructed away */
  const url=new URLSearchParams(location.search);
  FIELDS.forEach(k=>url.delete(k));
  for(const [k,v] of params())url.set(k,v);
  url.set("hero",heroKind);
  const qs=url.toString();
  /* Each new search is a step a reporter can walk back. Load-more and the hero
     switch are not steps, so they replace instead of pushing. */
  if(popping||!booted||qs===location.search.slice(1)) history.replaceState(null,"","?"+qs);
  else history.pushState(null,"","?"+qs);
  /* A name in the address bar that this page does not know is not a harmless
     extra: the page would answer with the whole file while the link claims a
     selection. It goes through the same refusal as a bad value, so there is one
     voice for "no number was produced". */
  /* A table of the whole corpus is not an answer to anything, and it arrives before the
     reporter has asked. The hero still shows the shape of the whole file; the rows
     wait until something has been chosen, or until "Read the ..." is clicked. */
  if(!REVEALED && ![...params().keys()].filter(k=>k!=="hero").length){
    el("count").innerHTML=`<strong>${num(TOTAL)} reports.</strong> Nothing chosen yet.`;
    el("results").innerHTML=`<table class="reports"><tr class="empty"><td>
      <p><strong>No rows yet, on purpose.</strong> Listing everything answers no question and
      buries the one you have.</p>
      <p class="muted">Take a month, a zone, an airline or a tail from the instrument above,
      pick one of the starter questions, or set a filter. To read the file straight through
      anyway, use the button at the foot of the instrument.</p>
      <div class="bar"><button class="ghost" onclick="revealAll()">Read all ${num(TOTAL)} anyway</button>
        <button class="ghost" onclick="showStarters()">Show me the starter questions</button></div></td></tr></table>`;
    el("more").style.display="none";
    ["exportBtn","copyBtn"].forEach(k=>{const e=el(k); if(e)e.disabled=true});
    await loadHero();
    return;
  }
  const stray=strayParams();
  /* a value a control refused to hold is the same failure one layer down: the link
     asks for something the page cannot set, so it must not answer with everything */
  const refused=Object.keys(UNRESOLVED).filter(k=>FIELDS.includes(k));
  const halt=stray.concat(refused);
  const say=[];
  if(stray.length)say.push("This link uses "+(stray.length===1?"a name":"names")
    +" this tool has no filter for: "+stray.join(", ")
    +". It was probably written for an older version of this page");
  if(refused.length)say.push("This link asks for "
    +refused.map(k=>(LABEL[k]||k)+" "+UNRESOLVED[k]).join(", ")
    +", which is not a value this data holds");
  const resp=halt.length?null:await fetch("api/search?"+p);
  const r=halt.length
    ? {rejected:Object.assign(
         Object.fromEntries(stray.map(k=>[k,new URLSearchParams(location.search).get(k)])),
         Object.fromEntries(refused.map(k=>[k,UNRESOLVED[k]]))),
       message:say.join(". ")+", so no query was run rather than answering with all "
         +num(TOTAL)+" reports."}
    : await resp.json();
  if((halt.length||resp.status===400)&&r.rejected){
    /* the server refused to run the query, so the page must not print a number */
    Object.assign(UNRESOLVED,r.rejected); chips();
    el("count").innerHTML=`<strong>No search was run.</strong>`;
    el("results").innerHTML=`<table class="reports"><tr class="empty"><td>
      <p><strong>${esc(r.message)}</strong></p>
      <div class="bar">${Object.keys(r.rejected).map(k=>
        `<button class="ghost" onclick="${FIELDS.includes(k)?`dropRefused('${k}')`:`dropStray('${k}')`}"
          >Drop ${esc(LABEL[k]||k)}</button>`).join("")}
        <button class="ghost" onclick="resetAll()">Clear all filters</button></div></td></tr></table>`;
    heroData=null; drawHero();
    /* nothing ran, so nothing may be exported or linked to as a result */
    ["exportBtn","copyBtn"].forEach(k=>{const e=el(k); if(e)e.disabled=true});
    return;
  }
  ATA=r.ata||ATA; chips();
  LAST_TOTAL=r.total;
  if(offset===0)CASE_ORDER=r.rows.map(x=>x.OperatorControlNumber);
  else CASE_ORDER=CASE_ORDER.concat(r.rows.map(x=>x.OperatorControlNumber));
  syncMoreFilters();
  document.querySelectorAll(".panel.on").forEach(p=>scopeLine(p.id));
  el("count").innerHTML=[...params().keys()].filter(k=>k!=="hero").length
    ? `<strong>${r.total.toLocaleString("en")}</strong> ${r.total===1?"report matches":"reports match"} your selection`
    : `<strong>${r.total.toLocaleString("en")}</strong> reports, nothing filtered yet`;
  const xb=el("exportBtn");
  if(xb){
    if(r.total>5000){
      xb.textContent=`Export CSV (newest 5,000 of ${r.total.toLocaleString("en")})`;
      xb.title="Ordered newest first. The oldest reports are not in this file. Narrow with a date range to export the rest.";
    }else if(r.total===0){ xb.textContent="Export CSV (0 rows)"; xb.title=""; xb.disabled=true; }
    else{ xb.textContent="Export CSV"; xb.title=""; xb.disabled=false; }
    const cb=el("copyBtn"); if(cb)cb.disabled=false;
  }
  loadHero();
  el("more").style.display=(offset+100<r.total)?"":"none";
  /* the header row on its own, so it can be repeated down a long table without
     starting a second table, which is exactly what a naive repeat of `head` did */
  const headRow=`<tr><th>Date</th><th>Operator</th><th>Aircraft</th><th>Tail</th>
    <th>System</th><th>Part</th><th>What was found</th><th>Crew did</th><th>Found by</th>
    <th>Stage</th><th></th></tr>`;
  const dateSorted=!(el("q")&&false);
  const cut=`<div class="cut">
    <span class="cs">${sentenceHTML(heroData||{total:r.total,corpus:TOTAL})}</span>
    <span class="cm">
      <span class="${r.total>1?"lit":""}">newest first, ties broken on the control number</span>
      <span class="${r.undated?"lit":""}">${r.undated
        ? `${num(r.undated)} carry no date, filed at the end`
        : "every report carries a date"}</span>
      <span class="${r.total>100?"lit":""}">${r.total>100
        ? `${num(Math.min(r.total,offset+100))} shown of ${num(r.total)}`
        : `all ${num(r.total)} shown`}</span>
      <button class="backup" onclick="scrollTo({top:0,behavior:'smooth'})">&uarr; back to the instrument</button>
    </span></div>`+sameDayRuns(r.rows);
  const head=`<p class="swipehint">Swipe the table sideways for System, Part, what was found, what the
    crew did, how it was found, the stage of flight and the report button.</p>
    `+cut+`<div class="tscroll"><table class="reports">`+headRow;
  LASTMONTH=null;
  const body=r.rows.map((x,i)=>{
    const j=x._jasc||{}, ch=j.chapter||"", d=(x.DifficultyDate||"").slice(0,10);
    const opLab=opName(x.OperatorDesignator);
    const zoneKey=(x.PartLocation||"").toUpperCase().match(/^ZONE \d00/);
    const dp=(x.DifficultyDate||"").split("/");
    const mKey=dp.length===3?`${dp[2]}-${dp[0].padStart(2,"0")}`:"";
    const spine=(mKey&&mKey!==LASTMONTH)?(LASTMONTH=mKey,
      `<tr class="spine" data-spine="${esc(mKey)}"><td colspan="11">
        <span>${esc(monthName(mKey))}</span>
        <b class="spinen"></b>
      </td></tr>`):"";
    return `${i&&i%25===0?headRow:""}${spine}
    <tr class="rep" data-month="${esc(mKey)}" data-zone="${zoneKey?zoneKey[0]:""}">
    <td>${esc(ukDate(x.DifficultyDate))}<div class="muted">N${esc(x.RegistryNNumber)||"&mdash;"}</div></td>
    <td>${x.OperatorDesignator
      ? `<span class="c" data-x="operator|${esc(x.OperatorDesignator)}" onclick="setFilter('operator','${esc(x.OperatorDesignator)}')">${esc(opLab||x.OperatorDesignator)}</span>`
      : `<span class="absent term" ${jt(NO_OPERATOR)}>no operator named</span>`}</td>
    <td><span class="c" data-x="aircraft|${esc(x.AircraftMake)}|${esc(x.AircraftModel)}" onclick="setFilter('model','${esc(x.AircraftModel)}')">${esc(x.AircraftMake)} ${esc(x.AircraftModel)}</span></td>
