function makeReachable(root){
  (root||document).querySelectorAll('[onclick]:not(button):not([tabindex])').forEach(e=>{
    e.setAttribute("tabindex","0");
    if(!e.getAttribute("role"))e.setAttribute("role","button");
    if(e.tagName==="B"&&e.parentElement&&e.parentElement.classList.contains("chip"))
      e.setAttribute("aria-label","Remove filter "+e.parentElement.textContent.replace("×","").trim());
  });
