/* The results table is a grid, not 1,240 stops in the tab order. Tab lands on it
   once; arrow keys move the roving focus; Enter fires whatever the cell does. */
function gridify(){
  /* every reports table, not only the first: the dossier and the corrosion table
     carried hundreds of tab stops because this used querySelector */
  document.querySelectorAll("table.reports").forEach(t=>{
    t.setAttribute("role","grid");
    [...t.querySelectorAll("tr")].forEach(r=>{
      r.setAttribute("role","row");
      [...r.children].forEach(c=>c.setAttribute("role", c.tagName==="TH"?"columnheader":"gridcell"));
    });
    /* keep whichever stop exists, including one that currently has focus, so a
       tooltip re-render cannot leave the table unreachable */
    const cur=t.querySelector('[tabindex="0"]')||(t.contains(document.activeElement)?document.activeElement:null);
    t.querySelectorAll('[tabindex="0"],button,a[href]').forEach(e=>e.setAttribute("tabindex","-1"));
    const keep=(cur&&t.contains(cur)?cur:null)||t.querySelector('tr.rep [role="button"],tr.rep button');
    if(keep)keep.setAttribute("tabindex","0");
  });
}
function gridKeys(e){
  const t=e.target.closest?.("table.reports"); if(!t)return;
  if(!["ArrowRight","ArrowLeft","ArrowDown","ArrowUp","Home","End"].includes(e.key))return;
  const items=[...t.querySelectorAll('[role="button"],button')].filter(x=>x.offsetParent!==null);
  const i=items.indexOf(document.activeElement); if(i<0)return;
  e.preventDefault();
  const rowLen=Math.max(1,[...t.querySelectorAll("tr.rep")][0]?.querySelectorAll('[role="button"],button').length||1);
  let n=i;
  if(e.key==="ArrowRight")n=Math.min(items.length-1,i+1);
  if(e.key==="ArrowLeft")n=Math.max(0,i-1);
  if(e.key==="ArrowDown")n=Math.min(items.length-1,i+rowLen);
  if(e.key==="ArrowUp")n=Math.max(0,i-rowLen);
  if(e.key==="Home")n=0;
  if(e.key==="End")n=items.length-1;
  items[i].setAttribute("tabindex","-1");
  items[n].setAttribute("tabindex","0"); items[n].focus();
}
