document.addEventListener("keydown",e=>{
  const t=e.target.closest&&e.target.closest('[role="tab"]');
  if(!t)return;
  const list=t.closest('[role="tablist"]')||t.parentElement;
  const tabs=[...list.querySelectorAll('[role="tab"]')].filter(x=>x.offsetParent!==null);
  const i=tabs.indexOf(t); if(i<0)return;
  let j=null;
  if(e.key==="ArrowRight")j=(i+1)%tabs.length;
  if(e.key==="ArrowLeft")j=(i-1+tabs.length)%tabs.length;
  if(e.key==="Home")j=0;
  if(e.key==="End")j=tabs.length-1;
  if(j===null)return;
  e.preventDefault();
  tabs.forEach(x=>x.setAttribute("tabindex","-1"));
  tabs[j].setAttribute("tabindex","0"); tabs[j].focus();
});
