/* Two panes drawn at independent scales are not a comparison, and a text box that
   only accepts four-letter codes asks the reporter to know the thing they came here
   to find out. Both panes now share one scale and one row order, and a typed name
   is resolved to its code. */
let FACET_OPS=[];
function resolveOperator(txt){
  const t=txt.trim().toUpperCase();
  if(!t)return {hits:[]};
  const exact=FACET_OPS.find(o=>o.toUpperCase()===t);
  if(exact)return {hits:[exact]};
  const byName=FACET_OPS.filter(o=>opName(o).toUpperCase().includes(t));
  return {hits:byName};
}
function setCompareDrill(field,val,ata){
  clearFields();
  const key={operator:"operator",model:"model",make:"make"}[field]||"operator";
  el(key).value=val; el("ata").value=ata;
  show("p-search"); search(0); showChange();
}
async function loadCompare(){
  const f=el("cmp-field").value;
  const raw={a:el("cmp-a").value.trim(), b:el("cmp-b").value.trim()};
  el("cmp-a-out").innerHTML=""; el("cmp-b-out").innerHTML="";
  if(!raw.a||!raw.b)return;
  if(!popping&&booted){
    const u=new URLSearchParams(location.search);
    u.set("view","compare"); u.set("cf",f); u.set("ca",raw.a); u.set("cb",raw.b);
    if(u.toString()!==location.search.slice(1))history.replaceState(null,"","?"+u.toString());
  }
  /* resolve both sides first, render both after: answering one side used to leave
     the other pane holding a stale card */
  const state={};
  for(const side of ["a","b"]){
    if(f!=="operator"){state[side]={kind:"ok",val:raw[side]};continue}
    const {hits}=resolveOperator(raw[side]);
    if(hits.length===1)state[side]={kind:"ok",val:hits[0]};
    else if(hits.length>1&&hits.length<=14)state[side]={kind:"ambiguous",hits};
    else state[side]={kind:"none"};
  }
  const pending=["a","b"].some(x=>state[x].kind!=="ok");
  if(pending){
    for(const side of ["a","b"]){
      const st=state[side], box=el("cmp-"+side+"-out");
      if(st.kind==="ok"){
        box.innerHTML=`<div class="card"><h2>${esc(opFull(st.val))}</h2>
          <p class="muted">Settled. <span class="c" onclick="el('cmp-${side}').value='';loadCompare()">change</span></p></div>`;
      }else if(st.kind==="ambiguous"){
        box.innerHTML=`<div class="card"><h2>Which one?</h2>
          <p class="muted">More than one operator matches &ldquo;${esc(raw[side])}&rdquo;.</p>
          <div class="chips">${st.hits.map(o=>`<span class="chip c"
            onclick="el('cmp-${side}').value='${esc(o)}';loadCompare()">${esc(opFull(o))}</span>`).join("")}</div></div>`;
      }else{
        const near=FACET_OPS.map(o=>opName(o))
          .filter(n=>n&&raw[side]&&n[0].toUpperCase()===raw[side][0].toUpperCase()).slice(0,3);
        box.innerHTML=`<div class="card"><h2>Not found</h2>
          <p class="muted">No operator in this data is called &ldquo;${esc(raw[side])}&rdquo;.
          ${near.length?"Did you mean "+near.map(esc).join(", ")+"?":""}</p></div>`;
      }
    }
    return;
  }
  const a=state.a.val, b=state.b.val;
  const r=await(await fetch(`api/compare?field=${f}&a=${encodeURIComponent(a)}&b=${encodeURIComponent(b)}`)).json();
  const order=r.order||[];
  /* one 0 to 100 scale of each side's own reports. Back to back raw counts made the
     bigger operator look worse at every row, which is the comparison the panel exists
     to prevent. */
  const MX=Math.max(1,...["a","b"].flatMap(k=>(r[k].systems||[]).map(x=>x.share)));
  for(const side of ["a","b"]){
    const sd=r[side], by={}; sd.systems.forEach(x=>by[x.ata]=x);
    const head=f==="operator"?opFull(sd.value):esc(sd.value);
    el("cmp-"+side+"-out").innerHTML=`<div class="card"><h2>${head}</h2>
      <div class="muted">${sd.total?num(sd.total)+" reports":"No reports match this value"}</div>
      <div class="bars cmp">${order.map(at=>{
        const x=by[at]||{n:0,share:0,label:ATA[at]||at,in_own_top:false};
        return `<div><span class="k c" title="${esc(x.label)}"
            onclick="setCompareDrill('${f}','${esc(sd.value)}','${at}')"><span class="kt">${esc(x.label)}</span></span>
          <span class="t"><span class="b" style="width:${Math.max(0.6,x.share/MX*100).toFixed(2)}%"></span></span>
          <span class="muted n">${x.share}%<span class="raw">${num(x.n)}</span></span>
          ${x.in_own_top?"":`<span class="cut">outside this side's own twelve most-reported</span>`}</div>`;
      }).join("")}</div>
      <p class="muted" style="margin-top:8px;font-size:11.5px">Bars are the share of
      ${esc(f==="operator"?opName(sd.value):sd.value)}&rsquo;s own ${num(sd.total)} reports, on one
      scale for both panes, so a row at the same length is the same share. Clicking a row searches
      ${esc(f==="operator"?opName(sd.value):sd.value)} only.</p></div>`;
  }
}


let popping=false, booted=false, LAST_TOTAL=null, LASTMONTH=null, CASE_ORDER=[];
let CREW_DEF="A crew action means the crew had to do something about it in flight or on the ground.";

/* ---- the instrument: Four Rails ---------------------------------------------
   The hero used to be a picture of the corpus standing next to a table it had
   nothing to do with. It is now four horizontal rails of the same selection, read
   left to right: when, where on the aircraft, whose aircraft, what it forced. One
   rail is open and operable, three rest and still read. Above them stands one
   sentence that is at once the selection, the count, the caveat carrier and the
   line a reporter can paste into a story. Nothing here is admirable before it is
   operable: there is no standalone trophy numeral anywhere. */

/* "Horizon", "Anatomy", "Swarm" and "Ledger" named the drawings, not the question.
   A reporter arriving cold learned nothing from them. */
const RAILS=[["when","WHEN","month by month","horizon"],
             ["where","WHERE","on the aircraft","anatomy"],
             ["whose","WHO","airline and tail","swarm"],
             ["forced","FORCED","what the crew did","ledger"]];
const HEROES=RAILS.map(r=>[r[3],r[2]]);
const GHOST="#d8d2c6";
let heroData=null, NARROWED=false;
/* the aircraft is where a reporter can point at something, so that is the rail the
   page opens on unless the address bar or a previous visit says otherwise */
/* the address bar still wins, so a shared link opens on the rail it names; a
   remembered rail no longer does, because the page is meant to open on the aircraft */
let heroKind=(new URLSearchParams(location.search).get("hero"))||"anatomy";
if(!HEROES.some(h=>h[0]===heroKind))heroKind="anatomy";
const railOf=k=>(RAILS.find(r=>r[3]===k)||RAILS[0])[0];
const heroOf=r=>(RAILS.find(x=>x[0]===r)||RAILS[0])[3];

/* Two selections in quick succession fire two requests, and the slower one can land
   last. That put the unfiltered total under the new filter's clause: "the whole corpus,
   reports, landing gear". Each request carries a sequence number, and a reply that
   has been overtaken is dropped rather than drawn. */
let heroSeq=0, HERO_FOR=null;
async function loadHero(){
  const p=params(), key=p.toString(), mine=++heroSeq;
  try{
    const hr=await fetch("api/hero?"+p);
    if(mine!==heroSeq)return;                 /* overtaken: this answer is stale */
    if(hr.status!==400){ heroData=await hr.json(); HERO_FOR=key; }
  }catch(e){ if(mine===heroSeq){ heroData=null; HERO_FOR=null; } }
  if(mine===heroSeq)drawHero();
}
function setHero(k){
  heroKind=k; localStorage.setItem("sdr_hero",k);
  const u=new URLSearchParams(location.search); u.set("hero",k);
  history.replaceState(null,"","?"+u.toString());
  drawHero();
}

/* ---- the aim line: the one element a pointer is allowed to write ---------- */
let aimTimer=null;
function aim(text,tone){
  const a=el("iAim");
  if(!a||a.dataset.hold||(HELD&&Date.now()<HELD.until))return;   /* an undo outranks a hover */
  a.className="aim"+(tone?" "+tone:""); a.innerHTML=text||"";
}
function unaim(){ const a=el("iAim");
  if(HELD&&Date.now()<HELD.until)return;
  if(a){delete a.dataset.hold;a.className="aim";a.innerHTML=""} }
let HELD=null;
function aimHold(text,secs){
  HELD={text, until: Date.now()+(secs||6)*1000};
  paintHeld();
  clearTimeout(aimTimer);
  aimTimer=setTimeout(()=>{ HELD=null; unaim(); }, (secs||6)*1000);
}
function paintSpines(){
  const ms=(heroData&&heroData.months)||[];
  document.querySelectorAll("tr.spine").forEach(r=>{
    const m=ms.find(x=>x.m===r.dataset.spine);
    const b=r.querySelector(".spinen"); if(b)b.textContent=m?`${num(m.n)} in this selection`:"";
  });
}
function paintHeld(){
  const a=el("iAim"); if(!a||!HELD||Date.now()>HELD.until)return;
  a.dataset.hold="1"; a.className="aim held"; a.innerHTML=HELD.text;
}
function takeFilter(field,value,label){
  setFilter(field,value);
  aimHold(`narrowed to ${esc(label||value)}. <button class="undoit"
    onclick="history.back();unaim()">undo</button>`);
}

/* ---- the standing sentence ------------------------------------------------ */
const CLAUSE_ORDER=["q","jasc","ata","part","condition","zone","operator","make","model",
                    "tail","crew","nature","discovered","stage","corrosion","minhours",
                    "cracked","from","to"];
function clauseText(k,v){
  if(k==="q")return `where a mechanic wrote &ldquo;${esc(v)}&rdquo;`;
  if(k==="operator")return esc(opName(v)||v);
  if(k==="ata")return esc(ATA[v]||v);
  if(k==="jasc")return esc((CODES.jasc&&CODES.jasc[v]&&CODES.jasc[v].label)||v);
  if(k==="zone")return esc(code("part_location",v)).toLowerCase();
  if(k==="crew")return esc(code("precaution",v)).toLowerCase();
  if(k==="tail")return "N"+esc(v);
  if(k==="cracked")return "with cracking recorded";
  if(k==="minhours")return `${num(+v)} hours or more on the airframe`;
  if(k==="from"||k==="to")return "";
  if(["nature","discovered","stage","corrosion"].includes(k))return esc(code(k,v)).toLowerCase();
  return esc(v);
}
function periodClause(){
  const f=el("from")&&el("from").value, t=el("to")&&el("to").value;
  if(!f&&!t)return "";
  const MON=["","January","February","March","April","May","June","July","August",
             "September","October","November","December"];
  const pretty=d=>{const [y,m,dd]=d.split("-").map(Number);return `${dd} ${MON[m].slice(0,3)} ${y}`};
  if(f&&t&&f.slice(0,7)===t.slice(0,7)&&f.slice(8)==="01"){
    const [yy,mm]=[+f.slice(0,4),+f.slice(5,7)];
    const lastDay=new Date(yy,mm,0).getDate();
    /* only call it a month when the whole month is in the selection */
    if(+t.slice(8)===lastDay)return `${MON[mm]} ${yy}`;
    return `1 to ${+t.slice(8)} ${MON[mm]} ${yy}`;
  }
  if(f&&t)return `${pretty(f)} to ${pretty(t)}`;
  return f?`from ${pretty(f)}`:`up to ${pretty(t)}`;
}
/* 05/08/2025 means 8 May in the file and reads as 5 August to this tool's readers */
const MONS=["","Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
function ukDate(us){
  const p=String(us||"").split("/");
  return p.length===3?`${+p[1]} ${MONS[+p[0]]} ${p[2]}`:String(us||"");
}
function prettyDate(iso){
  const MON=["","January","February","March","April","May","June","July","August",
             "September","October","November","December"];
  const [y,m,dd]=String(iso||"").split("-").map(Number);
  return (y&&m&&dd)?`${dd} ${MON[m]} ${y}`:String(iso||"");
}
function sentenceHTML(d){
  const p=params(), bits=[];
  for(const k of CLAUSE_ORDER){
    if(k==="from"||k==="to")continue;
    const v=p.get(k); if(!v)continue;
    bits.push(`<span class="clause" tabindex="0" data-drop="${k}"
      data-aim="drop-${k}">${clauseText(k,v)}</span>`);
  }
  const per=periodClause();
  if(per)bits.push(`<span class="clause" tabindex="0" data-drop="from|to"
    data-aim="drop-period">${esc(per)}</span>`);
  /* belt and braces: if the figures on hand were computed for a different
     selection, say so instead of pairing them with these words */
  if(d&&HERO_FOR!==null&&HERO_FOR!==params().toString())
    return `<b class="fig">&hellip;</b> counting ${bits.join(", ")}&hellip;`;
  const n=d?d.total:0, corpus=d?d.corpus:TOTAL;
  if(!bits.length)
    return `<b class="fig">${num(corpus)}</b> reports, everything the FAA has published to
            ${esc(prettyDate(RANGE.to))}.`;
  const aside=corpus-n;
  /* n + aside === corpus is true by construction, so it checked nothing. The real
     risk is the instrument and the table drifting apart. */
  const sums=!(d&&LAST_TOTAL!=null&&d.total!==LAST_TOTAL);
  return `<b class="fig">${num(n)}</b> ${n===1?"report":"reports"}, ${bits.join(", ")}.
    <span class="aside">${num(aside)} set aside.</span>` +
    (sums?"":`<span class="broken">the count above and the rows below disagree: reload before you
      quote either</span>`);
}

/* ---- the margin: a registry, not strings scattered through renderers ------ */
const MARGIN=[];
function marginPush(id,text,rust){ MARGIN.push({id,text,rust:!!rust}); }
function marginRender(){
  const m=el("iMargin"); if(!m)return;
  if(!MARGIN.length){ m.innerHTML='<span class="ash">Every figure here is a count of reports filed, not of flights.</span>'; return; }
  m.innerHTML=MARGIN.map(x=>`<span class="${x.rust?"rustnote":"ash"}">${x.text}</span>`).join("");
}

/* ---- rails ---------------------------------------------------------------- */
function gutter(r,value,open){
  if(open)return `<div class="gut"><div class="q">${r[1]}</div><div class="pn">${r[2]}</div>
    <div class="val">${value||""}</div></div>`;
  return `<div class="gut rest"><span class="q">${r[1]}</span>
    <span class="val">${value||""}</span></div>`;
}

/* A number on its own is a display, not a finding. Each rail states, in plain
   words, what its own figures amount to. Everything here is counted from the
   current selection, so it changes when the reporter narrows. */
/* A report reaches the FAA days to months after the event, so the newest months
   hold only part of what they will eventually hold. Reading their dip as a fall is
   the most available wrong story in this data. */
function settled(m){
  const cut=(heroData&&heroData.lag&&heroData.lag.settled_before)||null;
  if(!cut||!m||m.length!==7)return true;
  const [y,mo]=m.split("-").map(Number);
  const end=new Date(Date.UTC(y,mo,0));            /* last day of that month */
  return end<=new Date(cut+"T00:00:00Z");
}
function rate(n,days){
  if(!n||!days||n<30||days<60)return "";
  const per=days/n;
  if(per>=1.5)return `about one every ${Math.round(per)} days`;
  return `about ${(n/days).toFixed(1)} a day`;
}
const WORDS=["","one","two","three","four","five","six","seven","eight","nine","ten"];
const spell=n=>WORDS[n]||num(n);
/* The shorthand below is what the mechanic typed. This is the same report as the
   FAA itself files it: every part a lookup in their code tables, nothing inferred.
   "Not reported" and "Other" are dropped because they tell the reader nothing. */
function specLine(sp){
  if(!sp)return "";
  const dead=["","Other","Not reported","Unknown","None"];
  const norm=x=>String(x||"").toLowerCase().replace(/[^a-z]/g,"");
  /* the part name is often the system said again ("Tire" under "Tire"), which reads
     as two facts when it is one */
  const sys=sp.system, part=sp.part;
  const dup=part&&sys&&(norm(sys).includes(norm(part))||norm(part).includes(norm(sys)));
  const bits=[sp.aircraft,sys,dup?"":part,sp.condition,sp.found,sp.stage]
    .filter(x=>x&&!dead.includes(x));
  if(sp.date)bits.push(prettyDate(sp.date));
  if(!bits.length)return "";
  return `<div class="spec-decoded">${bits.map(esc).join(" &middot; ")}</div>`;
}
/* the stamp used to assert 2024; it now reads the range the data actually has */
function stampRange(){
  const f=String(RANGE.from||"");
  if(f.length<10)return "";
  return `${+f.slice(8,10)} ${(MONTHS[+f.slice(5,7)]||"").slice(0,3).toUpperCase()} ${f.slice(0,4)}`;
}
function stampTo(){
  const t=String(RANGE.to||"");
  if(t.length<10)return t.toUpperCase();
  return `${+t.slice(8,10)} ${(MONTHS[+t.slice(5,7)]||"").slice(0,3).toUpperCase()} ${t.slice(0,4)}`;
}
function reading(kind,d){
  const tot=d.total||0; if(!tot)return "";
  const days=(d.span&&d.span.days)||0;
  const pct=(a,b)=>b?(Math.round(a/b*1000)/10).toFixed(1):"0.0";
  let out="";
  if(kind==="when"){
    const all=(d.months||[]).filter(m=>!partialMonth(m.m));
    const full=all.filter(m=>settled(m.m));
    const young=all.length-full.length;
    if(full.length<2)return "";
    const hi=full.reduce((a,b)=>b.n>a.n?b:a), lo=full.reduce((a,b)=>b.n<a.n?b:a);
    out=`Between ${num(lo.n)} and ${num(hi.n)} reports in a settled month, `
       +`busiest in ${monthName(hi.m)}, quietest in ${monthName(lo.m)}.`;
    if(full.length>=24){
      const last=full.slice(-12), prev=full.slice(-24,-12);
      const av=a=>Math.round(a.reduce((s,x)=>s+x.n,0)/a.length);
      const a=av(last), bb=av(prev), diff=pct(Math.abs(a-bb),bb);
      out+=` The last twelve settled months average ${num(a)} a month against ${num(bb)} `
         +`for the twelve before, a difference of ${diff}%.`;
    }
    if(young){
      const lag=(d.lag&&d.lag.p95_days)||0;
      out+=` The ${young===1?"most recent month is":spell(young)+" most recent months are"} left out `
         +`of those figures: reports still arrive up to ${num(lag)} days after the event, `
         +`so ${young===1?"it holds":"they hold"} only part of what ${young===1?"it":"they"} will hold. `
         +`The dip at the right of the chart is the post arriving late, not fewer faults.`;
    }
  }
  if(kind==="where"){
    const zs=(d.zones||[]).slice().sort((a,b)=>b.n-a.n);
    if(!zs.length)return "";
    const zoned=zs.reduce((s,z)=>s+z.n,0);
    const blank=d.no_location||0, worded=d.other_location||0;
    /* This used to read "the others never say where", which was false: they nearly
       all say where, in words the diagram cannot place. Only the blank ones say
       nothing, and they are about one report in twenty-seven, not four fifths of the file. */
    out=`${zs[0].label} accounts for ${num(zs[0].n)} of the ${num(zoned)} reports written `
       +`in the FAA&rsquo;s numbered zones, or ${pct(zs[0].n,zoned)}%. Those numbers are what `
       +`this diagram can place, and they are ${pct(zoned,tot)}% of the selection.`;
    if(worded)out+=` Another ${num(worded)} do say where, in words such as FUSELAGE or `
       +`CABIN rather than a zone number, so the drawing cannot show them.`;
    if(blank)out+=` Only ${num(blank)}, ${pct(blank,tot)}%, give no location at all.`;
    /* Zonder deze zin leest de alinea als een reeks voorbehouden. De tekening is
       een steekproef, maar wel een die laat zien waar het meeste stukgaat. */
    out+=` It is a sample rather than the whole file, but it does give you a good `
       +`idea of where the trouble sits.`;
  }
  if(kind==="whose"){
    const ops=(d.operator_rows||[]), nOps=d.operators||0;
    if(ops.length&&nOps>ops.length){
      const top=ops.reduce((s,r)=>s+r.n,0);
      out=`${spell(ops.length)} operators file ${pct(top,tot)}% of what is here; `
         +`the other ${num(nOps-ops.length)} share the rest.`;
      out=out.charAt(0).toUpperCase()+out.slice(1);
    } else {
      out=`${num(nOps)} ${nOps===1?"operator files":"operators file"} everything here.`;
    }
    out+=` ${num(d.aircraft||0)} aircraft appear in all.`;
    const sw=(d.swarm||[])[0];
    if(sw&&sw.n>1)out+=` One of them, N${sw.t}, is written up ${num(sw.n)} times.`;
  }
  if(kind==="forced"){
    const cr=d.crew_reports||0;
    if(!cr)return `<p class="reading">No report in this selection records an action the `
      +`crew had to take. Everything here was found on the ground.</p>`;
    out=`${num(cr)} reports, ${pct(cr,tot)}% of this selection, record something the crew `
       +`had to do rather than something found on the ground.`;
    const top=(d.crew||[]).filter(x=>!["K","0","O"].includes(x.code))
      .slice().sort((a,b)=>b.n-a.n)[0];
    if(top){
      const r=rate(top.n,days);
      out+=` The commonest is ${top.label.toLowerCase()}, ${num(top.n)} times`+(r?`, ${r}.`:".");
    }
  }
  return out?`<p class="reading">${out}</p>`:"";
}
function railWhen(d,open){
  const ms=d.months||[]; if(!ms.length)return "";
  const cmax=Math.max(1,...ms.map(m=>m.all)), smax=Math.max(...ms.map(m=>m.n),0);
  const H=open?84:14;
  const cols=ms.map(m=>{
    const part=partialMonth(m.m)||!settled(m.m);
    const ch=(m.all/cmax)*H, sh=NARROWED?(m.n/cmax)*H:0;
    return `<span class="mo${part?" part":""}" style="height:${H}px"
      data-aim="month|${esc(m.m)}" tabindex="${open?0:-1}"
      role="${open?"button":"presentation"}"
      aria-label="${esc(monthName(m.m))}, ${num(m.n)} reports${
        partialMonth(m.m)?", a part month":(settled(m.m)?"":", still filling up")}">
      <i class="ghostb" style="height:${ch.toFixed(1)}px"></i>
      ${sh?`<i class="selb" style="height:${sh.toFixed(1)}px"></i>`:""}
      ${part?`<i class="parth" style="height:${ch.toFixed(1)}px"></i>`:""}</span>`;
  }).join("");
  let mag="";
  if(open&&smax&&smax<cmax*0.25){
    const f=(cmax*0.62)/smax;
    const pts=ms.map((m,i)=>`${(i*(1000/(ms.length-1))).toFixed(1)},${(H-(m.n*f/cmax)*H).toFixed(1)}`).join(" ");
    mag=`<svg class="mag" viewBox="0 0 1000 ${H}" preserveAspectRatio="none" aria-hidden="true">
      <polyline points="${pts}" fill="none" stroke="#c44b28" stroke-width="1.5"
        vector-effect="non-scaling-stroke"/></svg>
      <span class="magnote">selection &times;${f.toFixed(1)} to be visible</span>`;
  }
  const axis=open?`<div class="axis">${ms.map(m=>
    `<span>${m.m.slice(5)==="01"?m.m.slice(0,4):""}</span>`).join("")}</div>`:"";
  /* 7px a month plus the gap, so a long run scrolls rather than shrinking to nothing */
  const wide=open&&ms.length>72;
  const mw=wide?`--mw:${ms.length*9}px;`:"";
  const val=periodClause()||`${(d.months||[]).length} months`;
  return `<div class="rail ${open?"open":""}" data-rail="when"${open?"":' onclick="setHero(\'horizon\')"'}>${gutter(RAILS[0],esc(val,open))}
    <div class="track" style="${mw}"><div class="months">${cols}</div>${mag}${axis}
    ${wide?`<div class="whenhint">${num(ms.length)} months, so the strip scrolls sideways.
      It opens at the most recent.</div>`:""}</div>
    ${open?reading("when",d):""}</div>`;
}
function railWhere(d,open){
  const zs=d.zones||[], mx=Math.max(1,...zs.map(z=>z.n));
  if(!open){
    const val=(params().get("zone"))?esc(code("part_location",params().get("zone"))):"all zones";
    return `<div class="rail" data-rail="where" onclick="setHero('anatomy')">${gutter(RAILS[1],val,false)}
      <div class="track"><div class="strip">${[...zs].sort((a,b)=>b.n-a.n).map(z=>
        `<span class="${params().get("zone")===z.code?"sel":""}" title="${esc(z.label)}: ${num(z.n)}"
          style="flex:${Math.max(1,z.n)}"></span>`).join("")}
        </div></div></div>`;
  }
  const o=z=>(0.10+0.80*(z/mx)).toFixed(3);
  const byCode={}; zs.forEach(z=>byCode[z.code]=z);
  const zn=c=>(byCode[c]||{n:0}).n;
  const shape=(c0,d2)=>{const c=c0.replace(/b$/,"");
    return `<path d="${d2}" fill="rgba(196,75,40,${o(zn(c))})" stroke="#7c746a"
      stroke-width="1.1" class="zone" data-aim="zone|${c}" data-take="zone|${c}"
      tabindex="${open?0:-1}" role="${open?"button":"presentation"}"
      aria-label="${esc((byCode[c]||{}).label||c)}, ${num(zn(c))} reports"/>`};
  const art=`<svg viewBox="0 0 600 132" class="plane" role="img"
    aria-label="Aircraft from the side, each zone shaded by how many reports name it">
    ${shape("ZONE 100","M30 66 C30 80 47 88 80 88 L470 88 C495 86 513 80 529 72 L502 66 Z")}
    ${shape("ZONE 200","M30 66 C30 52 47 44 80 44 L452 44 C481 44 503 36 541 18 L557 14 C541 40 525 58 512 66 Z")}
    ${shape("ZONE 300","M452 44 L492 7 L518 7 L523 41 Z")}
    ${shape("ZONE 300b","M512 48 L578 38 L580 47 L516 57 Z")}
    ${shape("ZONE 500","M236 87 L356 87 L318 108 L264 108 Z")}
    ${shape("ZONE 600","M262 80 L344 80 L322 90 L284 90 Z")}
    <ellipse cx="248" cy="99" rx="24" ry="9.5" fill="rgba(196,75,40,${o(zn("ZONE 400"))})"
      stroke="#7c746a" stroke-width="1.1" class="zone" data-aim="zone|ZONE 400"
      data-take="zone|ZONE 400" tabindex="${open?0:-1}" role="${open?"button":"presentation"}"
      aria-label="Engine nacelles and pylons, ${num(zn("ZONE 400"))} reports"/>
    <g class="zone" data-aim="zone|ZONE 700" data-take="zone|ZONE 700" tabindex="${open?0:-1}"
       role="${open?"button":"presentation"}" aria-label="Landing gear, ${num(zn("ZONE 700"))} reports">
      <path d="M118 88 L118 104 M288 88 L288 106" stroke="#8d857b" stroke-width="3" fill="none"/>
      <circle cx="118" cy="109" r="6" fill="rgba(196,75,40,${o(zn("ZONE 700"))})" stroke="#7c746a"/>
      <circle cx="281" cy="111" r="7" fill="rgba(196,75,40,${o(zn("ZONE 700"))})" stroke="#7c746a"/>
      <circle cx="297" cy="111" r="7" fill="rgba(196,75,40,${o(zn("ZONE 700"))})" stroke="#7c746a"/></g>
    <g class="zone" data-aim="zone|ZONE 800" data-take="zone|ZONE 800" tabindex="${open?0:-1}"
       role="${open?"button":"presentation"}" aria-label="Doors, ${num(zn("ZONE 800"))} reports">
      ${[96,190,348,424].map(x=>`<rect x="${x}" y="49" width="11" height="17" rx="3"
        fill="rgba(196,75,40,${o(zn("ZONE 800"))})" stroke="#7c746a"/>`).join("")}</g>
    <g class="zone" data-aim="zone|ZONE 900" data-take="zone|ZONE 900" tabindex="${open?0:-1}"
       role="${open?"button":"presentation"}" aria-label="Lavatories and galleys, ${num(zn("ZONE 900"))} reports">
      ${[122,372].map(x=>`<rect x="${x}" y="51" width="22" height="14" rx="3"
        fill="rgba(196,75,40,${o(zn("ZONE 900"))})" stroke="#7c746a"/>`).join("")}</g>
    <g fill="#f7f5f0" stroke="none" opacity=".8">
      ${[150,164,220,234,248,300,314,328,400,414].map(x=>
        `<rect x="${x}" y="54" width="6" height="7" rx="2"/>`).join("")}</g>
  </svg>`;
  const pads=[["nowhere",`no location given`,d.no_location||0],
              ["outside",`place named in words, not as a zone`,d.other_location||0]];
  const legend=open?`<div class="legend">${
    [...zs].sort((a,b)=>b.n-a.n).map(z=>`<div class="lrow zone" data-aim="zone|${z.code}"
      data-take="zone|${z.code}" tabindex="0" role="button">
      <i style="background:rgba(196,75,40,${o(z.n)})"></i><span>${esc(z.label)}</span>
      <b>${num(z.n)}</b></div>`).join("")}
    <div class="lsplit"></div>
    ${pads.map(([id,lab,n])=>`<div class="lrow pad" data-aim="pad|${id}" tabindex="0" role="button">
      <i class="padi"></i><span>${esc(lab)}</span><b>${num(n)}</b></div>`).join("")}
  </div>`:"";
  const placed=zs.reduce((a,z)=>a+z.n,0);
  const val=(params().get("zone"))?esc(code("part_location",params().get("zone"))):"all zones";
  const placedAll=zs.reduce((a,z)=>a+z.n,0);
  const note=(d.unzoned>0)?`<div class="zonenote">The aircraft above counts only the
    ${num(placedAll)} reports that use one of the FAA's numbered zones. In another
    ${num(d.other_location||0)} the mechanic wrote where it was in plain words, such as the part
    or the system, and ${num(d.no_location||0)} say nothing about where. Those two cannot be drawn
    on the aircraft, so they sit under it.</div>`:"";
  return `<div class="rail open" data-rail="where">${gutter(RAILS[1],val,open)}
    <div class="track two">${art}<div>${legend}${note}</div></div>
    ${reading("where",d)}</div>`;
}
function railWhose(d,open){
  const sw=(d.swarm||[]).slice(0,8);
  const mxA=Math.max(1,...sw.map(x=>x.n));
  /* counted over every report, not over the 900 airframes the swarm list caps at:
     that cap covered 35% of the corpus and understated Continental tenfold */
  const top=(d.operator_rows||[]).map(r=>[r.o,r.n]);
  const mxO=Math.max(1,...top.map(x=>x[1]));
  const rest=Math.max(0,(d.operators||0)-top.length);
  const colOps=`<div class="col"><div class="ch">Operators</div>${top.map(([o,n])=>
    `<div class="orow" data-aim="operator|${esc(o)}" data-take="operator|${esc(o)}"
      tabindex="${open?0:-1}" role="${open?"button":"presentation"}">
      <span class="on">${esc(opName(o))}</span>
      <span class="ob"><i style="width:${(n/mxO*100).toFixed(1)}%"></i></span>
      <b>${num(n)}</b></div>`).join("")}
    ${rest?`<div class="orow more" data-aim="more-ops">
      <span class="on ash">${num(rest)} more operators</span></div>`:""}</div>`;
  const colAc=`<div class="col"><div class="ch">Airframes</div>${sw.map(a=>
    `<div class="orow" data-aim="tail|${esc(a.t)}" data-take="tail|${esc(a.t)}"
      tabindex="${open?0:-1}" role="${open?"button":"presentation"}">
      <span class="on mono">N${esc(a.t)}</span>
      <span class="ob"><i style="width:${(a.n/mxA*100).toFixed(1)}%"></i></span>
      <b>${num(a.n)}</b></div>`).join("")}
    ${(d.swarm_total>(d.swarm||[]).length)?`<div class="orow more" data-aim="more-tails">
      <span class="on ash">${num(d.swarm_total-(d.swarm||[]).length)} more airframes, not ranked here</span></div>`:""}</div>`;
  const val=`${num(d.swarm_total||0)} aircraft`;
  if(!open)
    return `<div class="rail" data-rail="whose" onclick="setHero('swarm')">${gutter(RAILS[2],val,open)}
      <div class="track"><div class="strip">${top.map(([o,n])=>
        `<span class="${params().get("operator")===o?"sel":""}" title="${esc(opName(o))}: ${num(n)}"
          style="flex:${Math.max(1,n)}"></span>`).join("")}
        </div></div></div>`;
  return `<div class="rail open" data-rail="whose">${gutter(RAILS[2],val,open)}
    <div class="track two">${colOps+colAc}</div>
    ${reading("whose",d)}</div>`;
}
function railForced(d,open){
  const cr=d.crew_reports||0, tot=d.total||0;
  if(!open){
    const sh=tot?(cr/tot*100):0;
    return `<div class="rail" data-rail="forced" onclick="setHero('ledger')">${gutter(RAILS[3],
      `${num(cr,open)} of ${num(tot)}`)}<div class="track"><div class="restbar">
      <i style="width:${sh.toFixed(2)}%"></i></div></div></div>`;
  }
  const share=tot?(cr/tot*100):0;
  const rows=(d.crew||[]).filter(x=>!["K","0","O"].includes(x.code)).slice(0,8);
  const mx=Math.max(1,...rows.map(x=>x.n));
  const block=`<div class="fblock" data-aim="crewall">
    <i style="width:${share.toFixed(2)}%"></i>
    <span class="flab">${num(cr)} of ${num(tot)} forced a crew action</span></div>`;
  const list=open?`<div class="frows">${rows.map(x=>
    `<div class="orow wide${params().get("crew")===x.code?" taken":""}"
      data-aim="crew|${x.code}" data-take="crew|${x.code}" tabindex="0" role="button">
      <span class="on">${esc(x.label)}</span>
      <span class="ob"><i style="width:${(x.n/mx*100).toFixed(1)}%"></i></span>
      <b>${num(x.n)}</b></div>`).join("")}
    <div class="fnote">A report can carry four of these, so they add to more than ${num(cr)}.</div>
  </div>`:"";
  return `<div class="rail ${open?"open":""}" data-rail="forced">${gutter(RAILS[3],
    `${num(cr,open)} of ${num(tot)}`)}<div class="track">${block}${list}
    ${open?reading("forced",d):""}</div></div>`;
}

/* ---- the whole instrument ------------------------------------------------- */
function drawHero(){
  const box=el("hero"); if(!box)return;
  /* rust is reserved for a chosen selection. At rest the corpus stands in ash, so
     the reporter can see there is nothing selected without reading a word. */
  NARROWED=[...params().keys()].some(k=>k!=="hero");
  const d=heroData;
  const openR=railOf(heroKind);
  MARGIN.length=0;
  if(!d){
    /* a dark instrument tells the reporter nothing about why. The frame stands, and
       the sentence slot says which of the three rest states this is. */
    const refused=Object.keys(UNRESOLVED).length>0;
    box.className="instrument";
    box.innerHTML=`<div class="ipad">
      <div class="ihead"><div class="stamp">FAA SERVICE DIFFICULTY REPORTS &middot; ${esc(stampRange())} TO
        ${esc(String(RANGE.to||"").toUpperCase())}</div></div>
      <div class="sentence">${refused
        ? `One value in this link is not in this data, so no search was run. There is no number on
           this page to quote.`
        : `Reading ${num(TOTAL)} reports.`}</div>
      <div class="aim"></div>
      <div class="rails">${RAILS.map(r=>`<div class="rail">${gutter(r,
        refused?"all "+num(TOTAL)+", not your query":"",false)}
        <div class="track"><div class="strip"><span style="flex:1"></span></div></div></div>`).join("")}</div>
    </div>`;
    return;
  }

  if((d.months||[]).some(m=>partialMonth(m.m)))
  {
    const to=String(RANGE.to||""), dd=+to.slice(8,10)||0;
    const [yy,mm]=[to.slice(0,4),+to.slice(5,7)];
    const inMonth=new Date(yy,mm,0).getDate();
    marginPush("part",`${MONTHS[mm]} ${yy} covers 1 to ${dd} ${MONTHS[mm]}, so its bar counts `
      +`${dd} days against ${inMonth} in a whole one`,true);
  }
  if(d.swarm_total>(d.swarm||[]).length)
    marginPush("swarmcap",`the tail list shows the ${num((d.swarm||[]).length)} most-reported aircraft out of ${num(d.swarm_total)}; the airline list counts every report`);
  marginPush("basis","counts are of reports filed, not of flights");
  const blind=railBlind();
  if(blind.length)marginPush("blind",
    `no rail draws ${blind.length===1?blind[0]:blind.slice(0,-1).join(", ")+" or "+blind.slice(-1)}; that part of the selection lives only in the controls below`);

  const picker=`<div class="picker" role="tablist" aria-label="Which rail is open">${
    RAILS.map(r=>`<button role="tab" aria-selected="${r[3]===heroKind}"
      class="${r[3]===heroKind?"on":""}" onclick="setHero('${r[3]}')">
      <span class="q">${r[3]==="ledger"?"WHAT IT FORCED":r[1]}</span><span class="pn">${r[2]}</span></button>`).join("")}</div>`;

  const hand={when:"Drag across the months to take a period.",
              where:"Click a zone on the aircraft to keep only what was found there.",
              whose:"Click an airline or an airframe to follow it.",
              forced:"Click what the crew had to do."}[openR];

  const sctl=(d.specimen&&d.specimen.control)||"";
  /* it was the only thing on the page that showed a single report and could not be
     opened; now the whole block is the way in to it */
  const spec=(d.lines&&d.lines.length)?`<div class="specimen${sctl?" opens":""}"
    ${sctl?`role="button" tabindex="0" data-case="${esc(sctl)}"
      aria-label="Open the full report ${esc(sctl)}"`:""}>
    <div class="sh">One report from this selection. First the FAA&rsquo;s own filing of it,
      then the mechanic&rsquo;s words as written.${sctl?` <span class="opencue">Click to open the
      full report &rarr;</span>`:""}</div>
    ${specLine(d.specimen)}
    <div class="sl">${jargon(d.lines[0])}</div></div>`:"";

  const zero=(d.total===0)?`<div class="zero">
    <b>Nothing matches all of these at once.</b>
    ${(d.leave_one_out||[]).slice(0,3).map(x=>`<button class="ghost"
      onclick="setFilter('${x.drop}','')">Drop ${esc(LABEL[x.drop]||x.drop)} &rarr; ${num(x.would_give)} reports</button>`).join("")}
    </div>`:"";

  if(isPhone()){ drawPhone(d,zero); paintHeld(); syncControls(); return }
  box.className="instrument";
  box.innerHTML=`
  <div class="ipad">
    <div class="ihead">
      <div class="stamp">FAA SERVICE DIFFICULTY REPORTS &middot; ${esc(stampRange())} TO ${esc(stampTo())}</div>
      ${picker}
    </div>
    <div class="sentence" id="iSentence">${sentenceHTML(d)}</div>
    <div class="aim" id="iAim"></div>
    <div class="aimat">
      <label for="iAimAt">Aim at</label>
<select id="aimKind" aria-label="What kind of thing to look for">
        <option value="period">a month or year</option>
        <option value="operator">an airline</option>
        <option value="tail">a tail number</option>
        <option value="zone">a zone</option>
        <option value="jasc">a system code</option>
        <option value="">free text search</option>
      </select>
            <input id="iAimAt" autocomplete="off" role="combobox" aria-expanded="false"
        aria-controls="aimSug" aria-autocomplete="list"
        placeholder="a month or a year, e.g. August or 2025">
      <button class="ghost" onclick="aimAtGo()">Take it</button>
      <label class="aimday" for="aimDay">or one day<input id="aimDay" type="date" aria-label="One date"></label>
      <div class="aimsug" id="aimSug" role="listbox" hidden></div>
    </div>
    <div class="hand" id="iHand">${esc(hand)}
      <span class="kbd">Keyboard: arrows walk the months, Shift and an arrow extends, Enter takes it.</span>
      <span class="c" onclick="el('morefilters').open=true;el('morefilters').scrollIntoView({behavior:'smooth',block:'center'})">Or use the filters below.</span></div>
    ${zero}
    <div class="rails">
      ${railWhen(d,openR==="when")}
      ${railWhere(d,openR==="where")}
      ${railWhose(d,openR==="whose")}
      ${railForced(d,openR==="forced")}
    </div>
    ${spec}
    <div class="margin" id="iMargin"></div>
  </div>
  <button class="seam" onclick="goResults()">${d.total?`Read the ${num(d.total)} &rarr;`:"Nothing to read yet"}</button>`;
  const blindLate=railBlind();
  if(false)marginPush("blind",
    `no rail draws ${blind.length===1?blind[0]:blind.slice(0,-1).join(", ")+" or "+blind.slice(-1)}; that part of the selection lives only in the controls below`);
  const wtr=document.querySelector(".rail.open[data-rail=when] .track");
  if(wtr&&wtr.scrollWidth>wtr.clientWidth)wtr.scrollLeft=wtr.scrollWidth;
  marginRender();
  aimAtFill();
  paintHeld();
  rove();
  paintSpines();
  syncControls();
}
