/* the caveats that actually bite on THIS report, generated rather than boilerplate */
function casePublishNotes(d){
  const out=[];
  out.push(caseFromLink
    ? `You opened this report by its control number, so no selection was applied. It is evidence of
       what a mechanic filed, not of what happened.`
    : `This is one report of ${num(LAST_TOTAL||0)} in the selection you were looking at. It is
       evidence of what a mechanic filed, not of what happened.`);
  if(d.OperatorDesignator){
    const known=(CODES.operator||{})[d.OperatorDesignator];
    out.push(known
      ? `The operator name comes from the FAA's December 2006 cross-reference. Check current
         ownership before you name ${esc(opName(d.OperatorDesignator))} in print.`
      : `Operator code ${esc(d.OperatorDesignator)} is not in the FAA cross-reference used here, so
         no name is asserted.`);
  }
  if(d._corrosion&&String(d.CorrosionLevel)==="3")
    out.push(`Corrosion level 3 obliged the operator to notify the regulator within three days and to
      act across the fleet. That is a checkable fact you can put to them.`);
  if(d._discovered&&["B","D","E","M","T","U","X"].includes(d.HowDiscoveredCode))
    out.push(`This was found by instrument, so it was not visible from outside the aircraft.`);
  if((d._crew_all||[]).length)
    out.push(`The crew action recorded here is what the FAA form says the crew did, not a description
      of severity.`);
  out.push(`Quote the mechanic's words as filed. The FAA publishes no per-report permalink, so cite
    the control number and this desk's link.`);
  return out;
}
function closeCase(){
  if(el("case-wrap").style.display!=="flex")return;
  /* navigate first, then let popstate do the hiding: hiding first made the guard
     miss and dumped the reporter back on the Search tab every time */
  /* Back only belongs here when we pushed the entry ourselves. On a colleague's
     link the previous entry is another site. */
  if(pushedCase&&new URLSearchParams(location.search).get("case")){history.back();return}
  const u=new URLSearchParams(location.search);
  if(u.get("case")){ u.delete("case"); history.replaceState(null,"","?"+u.toString()); }
  hideCase();
}
function releaseTrap(){
  if(caseTrap){el("case-wrap").removeEventListener("keydown",caseTrap);caseTrap=null}
  document.querySelectorAll("[data-inerted]").forEach(n=>{n.inert=false;n.removeAttribute("data-inerted")});
}
function trapFocus(){
  releaseTrap();
  const wrap=el("case-wrap"), box=el("case-box");
  [...document.body.children, ...document.querySelectorAll(".wrap > *")]
    .filter(n=>n!==wrap&&!n.contains(wrap))
    .forEach(n=>{n.inert=true;n.setAttribute("data-inerted","1")});
  caseTrap=e=>{
    if(e.key!=="Tab")return;
    const f=[...box.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')]
      .filter(x=>x.offsetParent!==null);
    if(!f.length)return;
    const first=f[0], last=f[f.length-1];
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
  };
  wrap.addEventListener("keydown",caseTrap);
}
/* One delegated listener reading the record held in memory. The payload never goes
   through an HTML attribute, which is what broke this the first time. */
function copyBit(text,btn){
  const old=btn.textContent;
  navigator.clipboard.writeText(text).then(()=>{
    btn.textContent="copied"; setTimeout(()=>{btn.textContent=old},1500);
  }).catch(()=>{
    btn.textContent="copy failed, select the text"; setTimeout(()=>{btn.textContent=old},2600);
  });
}
