    `<dt>${esc(t)}</dt><dd>${esc(d)}</dd>`).join("");
  const titles={
    jasc:["Aircraft systems (JASC codes)","The system the report is about, at full four-digit precision. Chapter 32 is landing gear; 3230 is specifically its retraction and extension. The FAA text is its own filing instruction to the mechanic."],
    nature:["What was found","The nature of the condition. Note that R is a partial power loss, while a true flameout is X. They are easy to confuse and mean different things."],
    precaution:["What the crew did","The precautionary action taken. K means none of the listed actions, which is the ordinary case."],
    discovered:["How it was found","Whether someone saw it or an instrument found it. This is the difference between damage that was visible and damage that was not."],
    stage:["Stage of flight","Where in the flight, or on the ground, the trouble appeared."],
    submitter:["Who filed the report","The kind of organisation reporting, and the regulation they operate under."],
    corrosion:["Corrosion level","Graded by the FAA. Level 3 is the one that forces action across the fleet."],
    part_location:["Zones on the aircraft","Coarse locations used when a more precise station is not given."],
    time_since:["Time since what","Whether the hours quoted for a part run from its last overhaul, repair or inspection."],
    operator_type:["Type of operator","Airline or general aviation."],
    operator:["Airline codes (operator designators)","The FAA's four-letter code for the company that filed the report. Not the two-letter code on your ticket. Names are from the December 2006 cross-reference, so verify current ownership."],
    region:["FAA region",""],
