  el("codetables").innerHTML=`<p class="lede">Every coded field shown here, decoded from the FAA's
    own lookup tables. Checked against all ${num(TOTAL)} reports, these tables resolve every code
    that actually occurs, with none left over. Operator designators, district offices and corrosion
    grades are not in that zip and are sourced separately, as the method note explains.
    Click a code to filter the search by it.</p>`+
  Object.entries(titles).map(([g,[t,note]])=>{
    const entries=Object.entries(CODES[g]||{});
    if(!entries.length)return "";
