    if(ev.key==="Enter"){ev.preventDefault();loadTail(el("tail-in").value.trim())}});
  FIELDS.forEach(k=>{
    const e=el(k); if(!e)return;
    if(e.tagName==="SELECT"||e.type==="date")e.addEventListener("change",()=>search(0));
